import torch
import tilelang as T
import numpy as np

@T.prim_func
def max_reduce_kernel(
    A: T.Buffer((128, 4096, 4095), "float16"),
    B: T.Buffer((128, 4095), "float16")
):
    # Define the reduction dimension
    T.func_attr({"global_symbol": "max_reduce_kernel"})

    # Initialize shared memory for reduction
    shared_max = T.alloc_buffer((4096,), "float16", scope="shared")

    # Parallelize over batch and other dimensions
    for i in T.thread_binding(128, thread="blockIdx.x"):
        for j in T.thread_binding(4095, thread="blockIdx.y"):
            # Load data into shared memory
            for k in T.thread_binding(4096, thread="threadIdx.x"):
                if k < 4096:
                    shared_max[k] = A[i, k, j]

            # Synchronize threads
            T.evaluate(T.call_extern("handle", "tir_cuda_synchronize"))

            # Perform reduction in shared memory
            for k in T.reversed(range(1, 4096)):
                with T.block("reduce"):
                    T.reads(shared_max[0:k])
                    T.writes(shared_max[0:(k//2)])
                    if k % 2 == 0:
                        shared_max[k//2] = T.max(shared_max[k//2], shared_max[k])

            # Write result back to global memory
            if T.thread_binding(4096, thread="threadIdx.x") == 0:
                B[i, j] = shared_max[0]

class ModelNew(torch.nn.Module):
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        # Compile the TileLang kernel
        self.kernel = T.jit(max_reduce_kernel)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is on GPU and convert to fp16
        if not x.is_cuda:
            x = x.cuda()
        if x.dtype != torch.float16:
            x = x.to(torch.float16)

        # Prepare output tensor
        output_shape = list(x.shape)
        output_shape.pop(self.dim)
        output = torch.empty(output_shape, dtype=torch.float16, device=x.device)

        # Call TileLang kernel
        self.kernel(x, output)

        return output

